const settings = $('Settings').first().json;
const REQUIRED = settings.requiredFields.split(',').map((code) => code.trim()).filter(Boolean);
const LOCALE = settings.locale;
const CHANNEL = settings.channel;

const pick = (values, code) => {
  if (!values) return null;
  const common = values.common?.[code];
  if (common !== undefined && common !== null && common !== '') return common;
  const scoped = values.locale_specific?.[LOCALE]?.[code];
  if (scoped !== undefined && scoped !== null && scoped !== '') return scoped;
  return values.channel_locale_specific?.[CHANNEL]?.[LOCALE]?.[code] ?? null;
};

return $input.all().map((item) => {
  const product = item.json;
  const values = product.values ?? {};

  const missing = REQUIRED.filter((code) => {
    const value = pick(values, code);
    return value === null || value === undefined || value === '';
  });

  if (!product.family) missing.push('family');
  if (!(product.categories ?? []).length) missing.push('categories');

  const checks = REQUIRED.length + 2;

  return {
    json: {
      sku: product.sku,
      family: product.family ?? null,
      active: product.status === true || product.status === 1,
      missingFields: missing,
      hasGaps: missing.length > 0,
      completeness: Math.round(((checks - missing.length) / checks) * 100),
    },
    pairedItem: item.pairedItem,
  };
});

const rows = $input.first().json.products ?? [];
const total = rows.length;
const auditedAt = new Date().toISOString();

if (total === 0) {
  return [{ json: { total: 0, complete: 0, incomplete: 0, completeRate: 0, averageCompleteness: 0, worstOffenders: [], gapsByField: {}, auditedAt } }];
}

const incomplete = rows.filter((row) => row.hasGaps);
const gapsByField = {};

for (const row of incomplete) {
  for (const field of row.missingFields) {
    gapsByField[field] = (gapsByField[field] ?? 0) + 1;
  }
}

const worstOffenders = [...incomplete]
  .sort((a, b) => a.completeness - b.completeness)
  .slice(0, 10)
  .map((row) => `${row.sku} (${row.completeness}%, missing ${row.missingFields.join(', ')})`);

return [{
  json: {
    total,
    complete: total - incomplete.length,
    incomplete: incomplete.length,
    completeRate: Math.round(((total - incomplete.length) / total) * 100),
    averageCompleteness: Math.round(rows.reduce((sum, row) => sum + row.completeness, 0) / total),
    worstOffenders,
    gapsByField,
    auditedAt,
  },
}];

